1718|   
1719|   // Parse ELF header
1720|   const elfHeader = parseElfHeader(fileBuffer);
1721|   
1722|   // Parse section headers
1723|   const sectionHeaders = parseSectionHeaders(fileBuffer, elfHeader);
1724|   
1725|   // Get section header string table
1726|   const shstrtab = getSectionData(fileBuffer, sectionHeaders[elfHeader.shstrndx]);
1727|   
1728|   // Find relevant sections
1729|   let textSection = null;
1730|   let dataSection = null;
1731|   let rodataSection = null;
1732|   let symbolTableSections = [];
