1734|   for (let i = 0; i < sectionHeaders.length; i++) {
1735|     const section = sectionHeaders[i];
1736|     const sectionName = getString(shstrtab, section.name);
1737|     
1738|     if (sectionName === '.text') {
1739|       textSection = section;
1740|     } else if (sectionName === '.data') {
1741|       dataSection = section;
1742|     } else if (sectionName === '.rodata') {
1743|       rodataSection = section;
1744|     } else if (section.type === SHT_SYMTAB) {
1745|       symbolTableSections.push(section);
1746|     }
1747|   }
1748|   
1749|   // Load sections into memory
1750|   const sectionsToLoad = [textSection, dataSection, rodataSection].filter(s => s !== null);
1751|   
1752|   for (const section of sectionsToLoad) {
1753|     const vaddr = section.addr;
1754|     const size = section.size;
1755|     const data = getSectionData(fileBuffer, section);
1756|     
1757|     // Load the section data into memory (assuming 4-byte words)
1758|     for (let i = 0; i < data.length; i += 4) {
1759|       if (i + 4 <= data.length) {
1760|         // For MIPS, we use little-endian byte order
1761|         const word = data.readUInt32LE(i);
1762|         memory[vaddr + i] = word;
1763|       }
1764|     }
1765|   }
1766|   
1767|   let entryPoint = 0; // Default entry point
1768|   const functionBounds = [];
1769|   
1770|   // Parse symbol tables
1771|   for (const symbolTableSection of symbolTableSections) {
1772|     // Get the associated string table
1773|     const strTabIdx = symbolTableSection.link;
1774|     const strTabSection = sectionHeaders[strTabIdx];
1775|     const strTab = getSectionData(fileBuffer, strTabSection);
1776|     
1777|     // Parse symbols
1778|     const entrySize = symbolTableSection.entsize;
1779|     const symbolData = getSectionData(fileBuffer, symbolTableSection);
1780|     
1781|     for (let offset = 0; offset < symbolData.length; offset += entrySize) {
1782|       const symbol = parseSymbol(symbolData, offset, elfHeader.class);
1783|       const symbolName = getString(strTab, symbol.name);
1784|       
1785|       if (symbolName) {
1786|         symbols[symbolName] = symbol.value;
1787|         invSymbols[symbol.value] = symbolName;
1788|         
1789|         if (STT_TYPE(symbol.info) === STT_FUNC) {
1790|           functionBounds.push([symbol.value, symbol.size, symbolName]);
1791|           
1792|           if (symbolName === 'main') {
1793|             entryPoint = symbol.value;
1794|           }
1795|         }
1796|       }
1797|     }
1798|   }
1799|   
1800|   // Sort function bounds by address
1801|   functionBounds.sort((a, b) => a[0] - b[0]);
1802|   
1803|   // Create mapping from each instruction address to its function
1804|   for (const [startAddr, size, funcName] of functionBounds) {
1805|     const endAddr = startAddr + size;
