1861|     shoff: Number(readAddr.call(buffer, elfClass === ELF_CLASS_64 ? 40 : 32)),
1862|     flags: readWord.call(buffer, elfClass === ELF_CLASS_64 ? 48 : 36),
1863|     ehsize: readHalf.call(buffer, elfClass === ELF_CLASS_64 ? 52 : 40),
1864|     phentsize: readHalf.call(buffer, elfClass === ELF_CLASS_64 ? 54 : 42),
1865|     phnum: readHalf.call(buffer, elfClass === ELF_CLASS_64 ? 56 : 44),
1866|     shentsize: readHalf.call(buffer, elfClass === ELF_CLASS_64 ? 58 : 46),
1867|     shnum: readHalf.call(buffer, elfClass === ELF_CLASS_64 ? 60 : 48),
1868|     shstrndx: readHalf.call(buffer, elfClass === ELF_CLASS_64 ? 62 : 50),
1869|     isLittleEndian
