1872| /**
1873|  * Parse section headers
1874|  * @param {Buffer} buffer - The ELF file buffer
1875|  * @param {Object} elfHeader - The parsed ELF header
1876|  * @returns {Array} Array of section headers
1877|  */
1878| function parseSectionHeaders(buffer, elfHeader) {
1879|   const sectionHeaders = [];
1880|   const isLittleEndian = elfHeader.isLittleEndian;
1881|   const readWord = isLittleEndian ? buffer.readUInt32LE : buffer.readUInt32BE;
1882|   const readXword = elfHeader.class === ELF_CLASS_64
