1888|   for (let i = 0; i < elfHeader.shnum; i++) {
1889|     const offset = elfHeader.shoff + i * sectionHeaderSize;
1890|     
1891|     const section = {
1892|       name: readWord.call(buffer, offset),
1893|       type: readWord.call(buffer, offset + 4),
1894|       flags: Number(readXword.call(buffer, offset + 8)),
1895|       addr: Number(readXword.call(buffer, offset + (elfHeader.class === ELF_CLASS_64 ? 16 : 12))),
1896|       offset: Number(readXword.call(buffer, offset + (elfHeader.class === ELF_CLASS_64 ? 24 : 16))),
1897|       size: Number(readXword.call(buffer, offset + (elfHeader.class === ELF_CLASS_64 ? 32 : 20))),
