  66| boolean M_FileExists(char *filename)
  67| {
  68|     FILE *fstream;
  69| 
  70|     fstream = fopen(filename, "r");
  71| 
  72|     if (fstream != NULL)
  73|     {
  74|         fclose(fstream);
  75|         return true;
  76|     }
  77|     else
  78|     {
