static unsigned char heap[32 * 1024 * 1024];
typedef struct HeapBlock
{
    size_t size;
    int free;
    struct HeapBlock *next;
} HeapBlock;

static HeapBlock *heap_head;

void *malloc(size_t size)
{
    HeapBlock *block;
    HeapBlock *next;
    size_t aligned;

    if (size == 0)
        size = 1;
    aligned = (size + 7) & ~(size_t)7;

    if (heap_head == NULL)
    {
        heap_head = (HeapBlock *)heap;
        heap_head->size = sizeof(heap) - sizeof(HeapBlock);
        heap_head->free = 1;
        heap_head->next = NULL;
    }

    for (block = heap_head; block != NULL; block = block->next)
    {
        if (!block->free || block->size < aligned)
            continue;

        if (block->size >= aligned + sizeof(HeapBlock) + 16)
        {
            next = (HeapBlock *)((unsigned char *)(block + 1) + aligned);
            next->size = block->size - aligned - sizeof(HeapBlock);
            next->free = 1;
            next->next = block->next;
            block->next = next;
            block->size = aligned;
        }
        block->free = 0;
        return block + 1;
    }

    return NULL;
}

void free(void *ptr)
{
    HeapBlock *block;
    HeapBlock *next;

    if (ptr == NULL)
        return;
    block = ((HeapBlock *)ptr) - 1;
    block->free = 1;
    next = block->next;
    if (next != NULL && next->free)
    {
        block->size += sizeof(HeapBlock) + next->size;
        block->next = next->next;
    }
}

void *calloc(size_t count, size_t size)
