void *realloc(void *ptr, size_t size)
{
    HeapBlock *block;
    void *result;
    size_t old_size;

    if (ptr == NULL)
        return malloc(size);
    if (size == 0)
    {
        free(ptr);
        return NULL;
    }
    block = ((HeapBlock *)ptr) - 1;
    old_size = block->size;
    if (old_size >= size)
