#define VM_MAX_FILES 32
typedef struct VMFile
{
    FILE *public_file;
    int guest_fd;
    int eof;
    int error;
    int used;
} VMFile;

static FILE stdin_storage;
static FILE stdout_storage;
static FILE stderr_storage;
static FILE file_storage[VM_MAX_FILES];
static VMFile file_info[VM_MAX_FILES];
FILE *stdin = &stdin_storage;
FILE *stdout = &stdout_storage;
FILE *stderr = &stderr_storage;

static VMFile *get_file(FILE *file)
{
    int i;
    if (file == stdin)
    {
        file_info[0].public_file = stdin;
        file_info[0].guest_fd = 0;
        file_info[0].used = 1;
        return &file_info[0];
    }
    if (file == stdout)
    {
        file_info[1].public_file = stdout;
        file_info[1].guest_fd = 1;
        file_info[1].used = 1;
        return &file_info[1];
    }
    if (file == stderr)
    {
        file_info[2].public_file = stderr;
        file_info[2].guest_fd = 2;
        file_info[2].used = 1;
        return &file_info[2];
    }
    for (i = 3; i < VM_MAX_FILES; ++i)
        if (file_info[i].used && file_info[i].public_file == file)
            return &file_info[i];
    return NULL;
}

int read(int fd, void *buffer, unsigned int count)
{
    return vm_syscall3(0, fd, (int)buffer, (int)count);
}

int write(int fd, const void *buffer, unsigned int count)
{
    return vm_syscall3(1, fd, (int)buffer, (int)count);
}

int open(const char *path, int flags, int mode)
{
    return vm_syscall3(2, (int)path, flags, mode);
}

int close(int fd)
{
    return vm_syscall1(3, fd);
}

long lseek(int fd, long offset, int whence)
{
    return vm_syscall3(8, fd, (int)offset, whence);
}

FILE *fopen(const char *path, const char *mode)
{
    int flags = VM_O_RDONLY;
    int fd;
    int i;

    if (mode[0] == 'w')
        flags = VM_O_WRONLY | VM_O_CREAT | VM_O_TRUNC;
    else if (mode[0] == 'a')
        flags = VM_O_WRONLY | VM_O_CREAT | VM_O_APPEND;
    if (mode[1] == '+')
        flags = VM_O_RDWR | VM_O_CREAT | (mode[0] == 'w' ? VM_O_TRUNC : 0);

    fd = open(path, flags, 0666);
    if (fd < 0)
    {
        errno = 2;
        return NULL;
    }
    for (i = 3; i < VM_MAX_FILES; ++i)
    {
        if (!file_info[i].used)
        {
            file_info[i].public_file = &file_storage[i];
            file_info[i].guest_fd = fd;
            file_info[i].eof = 0;
            file_info[i].error = 0;
            file_info[i].used = 1;
            if (flags & VM_O_APPEND)
                lseek(fd, 0, SEEK_END);
            return file_info[i].public_file;
        }
    }
    close(fd);
    errno = 24;
    return NULL;
}

int fclose(FILE *file)
{
    VMFile *info = get_file(file);
    if (info == NULL)
        return -1;
    if (info->guest_fd >= 3)
        close(info->guest_fd);
    if (info->guest_fd >= 3)
        info->used = 0;
    return 0;
}

size_t fread(void *buffer, size_t size, size_t count, FILE *file)
{
    VMFile *info = get_file(file);
    size_t bytes;
    int result;
    if (info == NULL || size == 0 || count == 0)
        return 0;
    bytes = size * count;
    result = read(info->guest_fd, buffer, (unsigned int)bytes);
    if (result < 0)
    {
        info->error = 1;
        return 0;
    }
    if ((size_t)result < bytes)
        info->eof = 1;
    return (size_t)result / size;
}

size_t fwrite(const void *buffer, size_t size, size_t count, FILE *file)
{
    VMFile *info = get_file(file);
    size_t bytes;
    int result;
    if (info == NULL || size == 0 || count == 0)
        return 0;
    bytes = size * count;
    result = write(info->guest_fd, buffer, (unsigned int)bytes);
    if (result < 0)
    {
        info->error = 1;
        return 0;
    }
    return (size_t)result / size;
}

int fseek(FILE *file, long offset, int whence)
{
    VMFile *info = get_file(file);
    if (info == NULL || lseek(info->guest_fd, offset, whence) < 0)
